UPDATE `#__guidedtours` SET `autostart` = 0;
INSERT INTO `#__guidedtours` (`title`, `uid`, `description`, `ordering`, `extensions`, `url`, `created`, `created_by`, `modified`, `modified_by`, `published`, `language`, `note`, `access`, `autostart`) VALUES ('Bloquear um artigo', 'joomlaguide-locking-an-article-pt-br', '<p>Quando alguém edita um artigo, o Joomla o <em>bloqueia</em>: ninguém mais pode alterá-lo ao mesmo tempo. Salvar ou fechar o artigo o <em>desbloqueia</em> de novo.</p><p>Se quem está editando sai sem salvar nem fechar, o artigo continua bloqueado. Neste tour você vê como isso acontece e como um administrador o desbloqueia.</p><p>Este tour segue o tutorial <a href="https://guide.joomla.org/pt-br/tutoriais/gerenciamento-de-conteudo/7-publicacao-e-acesso/7-5-bloqueando-um-artigo" target="_blank" rel="noopener">7.5 Bloqueando um Artigo</a> do Guia do Usuário do Joomla.</p>', 1, '["com_cpanel","com_content"]', 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', 'Joomla User Guide: 7.5 Locking an Article', 1, 1);
INSERT INTO `#__guidedtour_steps` (`tour_id`, `title`, `description`, `ordering`, `position`, `target`, `type`, `interactive_type`, `url`, `created`, `created_by`, `modified`, `modified_by`, `published`, `language`, `note`, `params`) VALUES
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-pt-br'), 'Conteúdo', '<p>No menu à esquerda, clique em <strong>Conteúdo</strong>.</p><p>Ele se abre e mostra o que você pode fazer ali.</p>', 1, 'right', 'body.com_cpanel #sidebarmenu li.item-level-1:has(a[href="index.php?option=com_content&view=articles"]) > a.has-arrow', 2, 4, 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-pt-br'), 'Conteúdo › Artigos', '<p>Clique em <strong>Artigos</strong>, em <strong>Conteúdo</strong>.</p>', 2, 'right', 'body.com_cpanel #sidebarmenu a[href="index.php?option=com_content&view=articles"]', 2, 1, 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-pt-br'), 'Abrir o artigo', '<p>Clique em <strong>Câmara Municipal Aprova Novo Orçamento de Transporte</strong> para editá-lo.</p>', 3, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" Câmara Municipal Aprova Novo Orçamento de Transporte"]) a[href*="task=article.edit"]', 2, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-pt-br'), 'Sair sem fechar', '<p>Agora você está editando o artigo. Não clique em <strong>Salvar</strong> nem em <strong>Fechar</strong>: pressione o botão <em>Voltar</em> do seu navegador. É o que faz quem sai sem fechar.</p><p>De volta à lista, o artigo tem um cadeado: ele está bloqueado. Passe o mouse sobre o cadeado para ver quem o bloqueou e quando. (Sem cadeado? Recarregue a página.)</p>', 4, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" Câmara Municipal Aprova Novo Orçamento de Transporte"]) th', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-pt-br'), 'Quem pode editá-lo?', '<p>Foi você quem bloqueou o artigo, então você ainda pode abri-lo. Outros usuários, mesmo administradores, recebem uma mensagem de erro quando tentam.</p><p>Quando você clica em <strong>Fechar</strong> ou <strong>Salvar & Fechar</strong> no artigo, ele é desbloqueado de novo.</p>', 5, 'bottom', '#articleList tr:has(a[href*="task=article.edit"][title$=" Câmara Municipal Aprova Novo Orçamento de Transporte"])', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-pt-br'), 'Desbloquear o artigo', '<p>Aqui quem estava editando não voltou. Como administrador, você pode desbloquear o artigo: clique no cadeado.</p>', 6, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" Câmara Municipal Aprova Novo Orçamento de Transporte"]) [data-item-task="articles.checkin"]', 2, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article-pt-br'), 'Muito bem!', '<p>O artigo está desbloqueado, e qualquer pessoa com permissão pode editá-lo de novo.</p><p>Para desbloquear muitos artigos de uma vez, marque as caixas de seleção deles e escolha <strong>Ações</strong> › <strong>Desbloqueado</strong>.</p><p>Cuidado: se a pessoa ainda estiver trabalhando no artigo, as alterações dela podem se perder.</p>', 7, 'bottom', '#system-message-container', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL);
